function make(inner: string, viewBox: string) {
  function Icon({ size, width, height, ...props }: IconProps) {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox={viewBox}
        width={size ?? width ?? 24}
        height={size ?? height ?? 24}
        {...props}
        dangerouslySetInnerHTML={{ __html: inner }}
      />
    );
  }
  return Icon;
}

